// Build a strict-JSON prompt for the local LLM.
// Etsy SEO rules baked in: title <= 140 chars, exactly 13 tags, each tag <= 20 chars.
const { shop_id, niche, kind = 'printable', cost = 0 } = $input.first().json.body || $input.first().json;

if (!shop_id || !niche) {
  throw new Error('shop_id and niche are required');
}

const system = `You are an Etsy SEO expert. Output ONLY valid minified JSON matching this schema:
{"title": string (<=140 chars, keyword-rich, no ALL CAPS),
 "tags": string[13] (each <=20 chars, lowercase, multi-word allowed, no duplicates),
 "description": string (3 short paragraphs: hook, features, usage),
 "suggested_price": number (USD, reflects ${kind === 'printable' ? 'high-margin digital' : 'POD with cost basis'} pricing)}
Cost basis (USD): ${cost}.`;

const user = `Niche / product description: ${niche}\nProduct kind: ${kind}`;

return [{ json: { shop_id, niche, kind, cost, prompt: `${system}\n\n${user}` } }];

// Parse + validate the LLM response.
const ollama = $input.first().json;
const input = $('Build Prompt').first().json;

let parsed;
try {
  parsed = typeof ollama.response === 'string' ? JSON.parse(ollama.response) : ollama.response;
} catch (e) {
  throw new Error(`LLM returned non-JSON: ${e.message}`);
}

const { title, tags, description, suggested_price } = parsed;
if (!title || typeof title !== 'string' || title.length > 140) {
  throw new Error('Invalid title');
}
if (!Array.isArray(tags) || tags.length !== 13) {
  throw new Error(`Expected 13 tags, got ${Array.isArray(tags) ? tags.length : 'none'}`);
}
if (tags.some(t => typeof t !== 'string' || t.length > 20)) {
  throw new Error('Tag too long (max 20 chars each)');
}
if (!description || typeof description !== 'string') {
  throw new Error('Invalid description');
}
const price = Number(suggested_price);
if (!Number.isFinite(price) || price <= 0) {
  throw new Error('Invalid suggested_price');
}

return [{
  json: {
    shop_id: input.shop_id,
    niche: input.niche,
    kind: input.kind,
    cost: input.cost,
    title,
    tags,
    description,
    suggested_price: price,
    ai_raw: parsed
  }
}];
